private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int octet = bb.get() & 0xFF;
        if ((octet & 0x80) == 0) {
            sb.append((char) octet);
        } else if ((octet & 0xE0) == 0xC0) {
            int ch = (octet & 0x1F) << 6;
            ch |= bb.get() & 0x3F;
            sb.append((char) ch);
        } else if ((octet & 0xF0) == 0xE0) {
            int ch = (octet & 0x0F) << 12;
            ch |= (bb.get() & 0x3F) << 6;
            ch |= bb.get() & 0x3F;
            sb.append((char) ch);
        } else if ((octet & 0xF8) == 0xF0) {
            int ch = (octet & 0x07) << 18;
            ch |= (bb.get() & 0x3F) << 12;
            ch |= (bb.get() & 0x3F) << 6;
            ch |= bb.get() & 0x3F;
            sb.append((char) ch);
        } else {
            // Invalid UTF-8 octet
            throw new IllegalArgumentException("Invalid UTF-8 octet: " + octet);
        }
        i++;
    }
    return i;
}
