private TreeNode<T> rotateRight(TreeNode<T> x) {
    TreeNode<T> y = x.left;
    x.left = y.right;
    if (y.right != null) {
        y.right.parent = x;
    }
    y.parent = x.parent;
    if (x.parent == null) {
        this.root = y;
    } else if (x == x.parent.right) {
        x.parent.right = y;
    } else {
        x.parent.left = y;
    }
    y.right = x;
    x.parent = y;
    return y;
}
