public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file parameter must not be null");
    }
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        if (!file.delete()) {
            throw new IOException("Deletion of file " + file + " was unsuccessful");
        }
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteDirectory(file);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }));
}

private static void deleteDirectory(File dir) throws IOException {
    File[] files = dir.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectory(file);
            } else {
                if (!file.delete()) {
                    throw new IOException("Deletion of file " + file + " was unsuccessful");
                }
            }
        }
    }
    if (!dir.delete()) {
        throw new IOException("Deletion of directory " + dir + " was unsuccessful");
    }
}
