public class TimeRangeSplitter {
    private static final long FETCH_DATA_DURATION = 3600000; // 1 hour in milliseconds

    /**
     * Split time ranges to ensure the start time and end time is smaller than {@link #FETCH_DATA_DURATION}
     */
    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        while (start < end) {
            long nextStart = start + FETCH_DATA_DURATION;
            if (nextStart > end) {
                timeRanges.add(new TimeRange(start, end));
                break;
            } else {
                timeRanges.add(new TimeRange(start, nextStart));
                start = nextStart;
            }
        }
        return timeRanges;
    }

    // Inner class to represent a time range
    public static class TimeRange {
        private final long start;
        private final long end;

        public TimeRange(long start, long end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public String toString() {
            return "TimeRange{" +
                    "start=" + start +
                    ", end=" + end +
                    '}';
        }
    }
}
