public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the compressed day based on the dayStep
    int compressedDay = day - (day - 1) % dayStep;

    // Reconstruct the time bucket with the compressed day
    return (long) year * 10000 + month * 100 + compressedDay;
}
