public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        int length = str.length();
        byte[] bytes = str.toString().getBytes("UTF-8");
        if (lb.getOffset() + bytes.length > lb.getCapacity()) {
            lb = session.expand(lb, bytes.length);
        }
        System.arraycopy(bytes, 0, lb.getData(), lb.getOffset(), bytes.length);
        lb.setOffset(lb.getOffset() + bytes.length);
    } catch (Exception e) {
        e.printStackTrace();
    }
    return lb;
