// Removes this edge from both doubly linked lists of tree edges.
public void removeFromTreeEdgeList() {
    // Assuming the edge has pointers to the previous and next edges in the list
    // Remove the edge from the previous edge's next pointer
    if (previous != null) {
        previous.next = next;
    }

    // Remove the edge from the next edge's previous pointer
    if (next != null) {
        next.previous = previous;
    }

    // Set the previous and next pointers of the edge to null
    previous = null;
    next = null;
}
