private static String subst(String str, Properties props) {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int startIndex = 0;
    int braceIndex = str.indexOf("${", startIndex);
    while (braceIndex != -1) {
        result.append(str, startIndex, braceIndex);
        int endIndex = str.indexOf("}", braceIndex);
        if (endIndex == -1) {
            result.append(str.substring(braceIndex));
            break;
        }
        String propKey = str.substring(braceIndex + 2, endIndex);
        String propValue = props.getProperty(propKey);
        if (propValue != null) {
            result.append(propValue);
        } else {
            result.append("${").append(propKey).append("}");
        }
        startIndex = endIndex + 1;
        braceIndex = str.indexOf("${", startIndex);
    }
    if (startIndex < str.length()) {
        result.append(str.substring(startIndex));
    }
    return result.toString();
}
