    try {
        String path = u.getPath();
        if (path != null) {
            if (path.startsWith("/")) {
                path = path.substring(1);
            }
            String[] parts = path.split("/");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    if (decode) {
                        part = URLDecoder.decode(part, "UTF-8");
                    }
                    segments.add(new PathSegmentImpl(part));
                }
            }
        }
    } catch (Exception e) {
        // Handle exception
    }
    return segments;
