private void pop(final String descriptor){
    int count = 1;
    if (descriptor.charAt(0) == '(') {
        int balance = 0;
        int i = 1;
        while (balance != 0) {
            char c = descriptor.charAt(i);
            if (c == '(') balance++;
            else if (c == ')') balance--;
            i++;
        }
        count = i - 1;
    }
    // Assuming outputFrameStack is a stack of AbstractType
    while (count > 0 && !outputFrameStack.isEmpty()) {
        outputFrameStack.pop();
        count--;
    }
}
