public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1000) {
        while (!isPrime(desiredCapacity)) {
            desiredCapacity++;
        }
    } else {
        int upperBound = (int) (desiredCapacity * 1.11);
        while (!isPrime(upperBound)) {
            upperBound++;
        }
        desiredCapacity = upperBound;
    }
    return desiredCapacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number == 2) {
        return true;
    }
    if (number % 2 == 0) {
        return false;
    }
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}
