public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    boolean inUnicode = false;
    int unicode = 0;
    int count = 0;

    for (int i = 0; i < str.length(); ++i) {
        char ch = str.charAt(i);
        if (inUnicode) {
            int digit = Character.digit(ch, 16);
            if (digit < 0) {
                throw new Exception("Illegal escape character");
            }
            unicode = (unicode << 4) + digit;
            if (++count < 4) {
                continue;
            }
            sb.append((char)unicode);
            inUnicode = false;
            continue;
        }
        if (ch == '\\') {
            inUnicode = true;
            count = 0;
            unicode = 0;
            if (i+1 == str.length()) {
                throw new Exception("Illegal escape character");
            }
            ch = str.charAt(++i);
        }
        switch (ch) {
            case 'b' -> sb.append('\b');
            case 't' -> sb.append('\t');
            case 'n' -> sb.append('\n');
            case 'f' -> sb.append('\f');
            case 'r' -> sb.append('\r');
            case '"' -> sb.append('"');
            case '\'' -> sb.append('\'');
            case '\\' -> sb.append('\\');
            default -> sb.append(ch);
        }
    }

    return sb.toString();
}

