public static String trimLeadingWhitespace(String str){
    if (str == null) {
        return null;
    }
    int len = str.length();
    int st = 0;
    while ((st < len) && Character.isWhitespace(str.charAt(st))) {
        st++;
    }
    return ((st > 0) || (st == len)) ? str.substring(st, len) : str;
}
