private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the circulator starting from the start node in the given direction
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Traverse along the outer face until the predicate is satisfied or the stop node is reached
    while (!predicate.test(circulator.node()) && !circulator.node().equals(stop)) {
        circulator.moveNext();
    }

    // Return the circulator pointing to the node that satisfies the predicate or the stop node
    return circulator;
}
