public byte[] putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteVector == null) {
        byteVector = new byte[byteLength];
    } else if (byteVector.length < byteLength) {
        byte[] newVector = new byte[byteLength];
        System.arraycopy(byteVector, 0, newVector, 0, byteVector.length);
        byteVector = newVector;
    }
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, byteVector, 0, byteLength);
    } else {
        java.util.Arrays.fill(byteVector, 0, byteLength, (byte) 0);
    }
    return byteVector;
}
