private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (Edge<E> edge : graph.edgeSet()) {
        Set<Integer> nodeU = graph.getVerticesOfEdge(edge).getFirst();
        Set<Integer> nodeV = graph.getVerticesOfEdge(edge).getSecond();
        Set<Integer> separator = findMinimalSeparator(graph, nodeU, nodeV);
        globalSeparatorList.add(new Pair<>(separator, edge));
    }
    return globalSeparatorList;
}

private Set<Integer> findMinimalSeparator(Graph<Integer, E> graph, int nodeU, int nodeV) {
    Set<Integer> separator = new HashSet<>();
    for (int node : graph.vertexSet()) {
        if (node != nodeU && node != nodeV) {
            Set<Integer> neighbors = new HashSet<>(graph.neighborsOf(node));
            neighbors.remove(nodeU);
            neighbors.remove(nodeV);
            if (!neighbors.isEmpty()) {
                boolean isSeparator = true;
                for (Edge<E> incidentEdge : graph.incidentEdgesOf(node)) {
                    if (incidentEdge != edge) {
                        int otherNode = graph.getVerticesOfEdge(incidentEdge).getFirst() == node ? graph.getVerticesOfEdge(incidentEdge).getSecond() : graph.getVerticesOfEdge(incidentEdge).getFirst();
                        if (!(neighbors.contains(otherNode) && graph.pathExists(nodeU, otherNode) && graph.pathExists(nodeV, otherNode))) {
                            isSeparator = false;
                            break;
                        }
                    }
                }
                if (isSeparator) {
                    separator.add(node);
                }
            }
        }
    }
    return separator;
}
