public int readTag() throws IOException {
    int firstByte = in.read();
    if (firstByte == -1) {
        return 0;
    }
    int tag = firstByte & 0x07;
    int wireType = firstByte >>> 3;
    if (wireType == 0) {
        // Varint for field number
        int shift = 0;
        int result = 0;
        while (shift < 28) {
            int b = in.read();
            if (b == -1) {
                throw new EOFException("Unexpected end of stream");
            }
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
        }
        tag = (tag << shift) | result;
    } else if (wireType == 5) {
        // 32-bit integer
        int result = in.readInt();
        if (result == Integer.MIN_VALUE) {
            throw new IOException("Invalid varint encoding found for integer field");
        }
        tag = (tag << 32) | result;
    } else {
        throw new IOException("Invalid wire type");
    }
    return tag;
}
